<?php require __DIR__.'/../app/bootstrap.php'; require_login();
$no=trim((string)($_GET['asset_no']??''));$st=db()->prepare('SELECT a.*,p.full_name personnel_name,p.personnel_code FROM assets a LEFT JOIN personnel p ON p.id=a.personnel_id WHERE a.asset_no=?');$st->execute([$no]);$asset=$st->fetch();if(!$asset){http_response_code(404);exit('تجهیز یافت نشد.');}$st=db()->prepare('SELECT * FROM asset_disks WHERE asset_no=? ORDER BY disk_index');$st->execute([$no]);$disks=$st->fetchAll();$st=db()->prepare('SELECT * FROM asset_ram_slots WHERE asset_no=? ORDER BY slot_no');$st->execute([$no]);$rams=$st->fetchAll();$tech=json_decode((string)$asset['technical'],true)?:[];$types=['computer'=>'پایگاه رایانه','printer'=>'چاپگر','display'=>'نمایشگر','scanner'=>'اسکنر'];$arrayFields=['IPAddresses','MACAddresses','SubnetMasks','Gateways','DNSServers','RAMManufacturers','RAMPartNumbers','RAMSerialNumbers','RAMSpeedsMHz','DiskModels','DiskSizesGB','DiskSerials','DiskInterfaces'];
