?><!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($asset['asset_no'])?> | پرونده تجهیز</title><link rel="stylesheet" href="assets/app.css"></head><body><header><a class="brand" href="index.php">سامانه سخت‌افزار</a><nav><a href="index.php">داشبورد</a><a href="assets.php">تجهیزات</a><a href="report.php">گزارش‌ها</a><?php if((user()['role']??'')==='admin'):?><a href="audit.php">رویدادها</a><?php endif;?><a href="logout.php">خروج</a></nav></header><main><div class="page-head"><div><h1>پرونده تجهیز <?=e($asset['asset_no'])?></h1><p class="muted"><?=e($types[$asset['asset_type']]??$asset['asset_type'])?> · آخرین بروزرسانی <?=e($asset['updated_at'])?></p></div><div class="actions"><?php if($asset['source_file']):?><a class="btn" href="source_download.php?asset_no=<?=urlencode($no)?>">دریافت CSV منبع</a><?php endif;?><?php if(can_manage_asset_type($asset['asset_type'],'edit')):?><a class="btn primary" href="asset_edit.php?asset_no=<?=urlencode($no)?>">ویرایش</a><?php endif;?></div></div><section class="detail-grid"><article class="panel"><h2>مشخصات عمومی</h2><dl><dt>شماره اموال</dt><dd><?=e($asset['asset_no'])?></dd><dt>نوع / زیرنوع</dt><dd><?=e(($types[$asset['asset_type']]??$asset['asset_type']).' / '.($asset['device_subtype']?:'—'))?></dd><dt>نام دستگاه</dt><dd><?=e($asset['hostname']?:'—')?></dd><dt>برند / مدل</dt><dd><?=e(trim(($asset['manufacturer']??'').' '.($asset['model']??''))?:'—')?></dd><dt>سریال</dt><dd><?=e($asset['serial_no']?:'—')?></dd><dt>پرسنل</dt><dd><?=e($asset['personnel_name']?:'—')?></dd><dt>کد پرسنلی</dt><dd><?=e($asset['personnel_code']?:'—')?></dd><dt>مکان</dt><dd><?=e($asset['location']?:'—')?></dd><dt>اداره / دانشکده</dt><dd><?=e($asset['department']?:'—')?></dd><dt>وضعیت</dt><dd><?=e(['active'=>'فعال','repair'=>'تعمیر','retired'=>'اسقاط','lost'=>'مفقود'][$asset['status']]??$asset['status'])?></dd></dl></article><article class="panel"><h2>اطلاعات 